from typing import TypeVar
T=TypeVar("T")
def cyclic_grid(basis: list[T]) -> list[list[T]]:
    n=len(basis)
    if n == 0: raise ValueError("basis must be nonempty")
    return [[basis[(i+j)%n] for j in range(n)] for i in range(n)]
if __name__ == "__main__":
    grid=cyclic_grid(["e0","e1","e2","e3"])
    for row in grid: print(row)
    print("columns:",*[list(col) for col in zip(*grid)],sep="\n")

