from fractions import Fraction
from itertools import permutations
from typing import TypeAlias
Vector: TypeAlias=tuple[Fraction,...]
def determinant(matrix: tuple[Vector,...]) -> Fraction:
    n=len(matrix)
    if n==0: return Fraction(1)
    return sum(((-1)**j)*matrix[0][j]*determinant(tuple(tuple(row[k] for k in range(n) if k!=j) for row in matrix[1:])) for j in range(n))
def search(rows: list[list[Vector]]) -> list[list[Vector]] | None:
    n=len(rows)
    for choices in __import__('itertools').product(*(permutations(row) for row in rows)):
        if all(determinant(tuple(choices[i][j] for i in range(n))) != 0 for j in range(n)):
            return [list(row) for row in choices]
    return None

